import json
from pathlib import Path
R=Path('/workspace/scratch/de85e7c60a94/manufacturing-complete');P=Path(__file__).parent
S=json.load(open(R/'src/data/manufacturing/source-guides.json'))['guides']
def write(locale,label,rows):
 assert len(rows)==len(S)
 out={}
 for s,r in zip(S,rows):
  title,obj,paras,terms,act,safety,summary=r
  assert len(paras)==len(s['paragraphs'])and len(terms)==len(s['terms'])and len(safety)==len(s['safetyJa'])
  out[s['id']]={'sourceHash':s['sourceHash'],'translatedDirectlyFrom':'ja','nativeReviewed':False,'domainReviewed':False,'status':'ai_translated_draft','title':title,'objective':obj,'paragraphs':[{'id':a['id'],'title':b[0],'text':b[1]}for a,b in zip(s['paragraphs'],paras)],'terms':[{'ja':a['ja'],'reading':a['reading'],'meaning':b}for a,b in zip(s['terms'],terms)],'activity':act,'safety':safety,'summary':summary}
 (P/'locales'/f'{locale}.json').write_text(json.dumps({'locale':locale,'uiLabel':label,'lessons':out,'nativeReviewed':False,'domainReviewed':False,'independentlyReviewed':False},ensure_ascii=False,indent=2)+'\n')
ID=[]
ID.append(('Memahami perbedaan 5S dan 4S melalui kegiatan berkelanjutan','Membedakan lima unsur 5S dan unsur yang dihilangkan pada 4S. Menghubungkan nama dengan tindakan sehari-hari.',[
('Mempertahankan lima unsur','5S terdiri atas pemilahan, penataan, pembersihan, pemeliharaan kebersihan, dan pembiasaan disiplin. Pemilahan menghilangkan benda yang tidak diperlukan; penataan menempatkan benda yang diperlukan di tempat yang ditentukan; pembersihan menghilangkan kotoran sambil menemukan kelainan kecil seperti kebocoran oli. Pemeliharaan kebersihan berarti mempertahankan keadaan baik hasil pemilahan, penataan, dan pembersihan; pembiasaan disiplin berarti semua orang menjadikan aturan yang disepakati sebagai kebiasaan.'),
('Jangan tertukar tentang unsur yang dihilangkan pada 4S','Materi memberikan contoh penamaan 4S untuk pemilahan, penataan, pembersihan, dan pemeliharaan kebersihan, yaitu 5S tanpa pembiasaan disiplin. Mengganti pembersihan dengan tanggung jawab lalu menyebutnya 5S, ataupun menambahkan tanggung jawab pada 4S, bukan penjelasan penamaan ini. Selain mengingat nama, pastikan tindakan apa yang harus terus dilakukan.'),
('Tidak selesai dalam satu kali kegiatan','5S bukan kegiatan yang selesai setelah satu kali beres-beres, melainkan dilakukan setiap hari untuk menghasilkan tempat kerja yang aman dan nyaman serta produk yang baik. Jangan membuang dokumen atau barang titipan atas keputusan sendiri. Jika menemukan kelainan, sampaikan kepada penanggung jawab dalam keadaan aman. Jangan memasukkan tangan ke bagian berputar untuk membersihkannya.')],
['Sebutan untuk gabungan pemilahan, penataan, pembersihan, dan pemeliharaan kebersihan.','Menjadikan aturan yang disepakati sebagai kebiasaan.','Terus melakukan, bukan hanya sekali.'],
'4 menit: tuliskan unsur 5S dan 4S secara terpisah.\n5 menit: baca teks dan jelaskan perbedaan pembersihan dan pemeliharaan kebersihan.\n4 menit: bayangkan tempat kerja, lalu tuliskan masing-masing dua tindakan yang dilakukan setiap hari dan penanggung jawab pemeriksaannya.\n2 menit: tinjau alasan mengapa tanggung jawab tidak boleh menggantikan pembersihan.',
['Belajar dilakukan di atas kertas. Patuhi kewenangan dan prosedur keselamatan tempat kerja saat membersihkan, membuang barang, atau mendekati peralatan.'],
'Jangan mengganti pembersihan pada 5S dengan tanggung jawab. 4S adalah penamaan yang menghilangkan pembiasaan disiplin; pertahankan keadaan baik setiap hari.'))
ID.append(('Memahami panduan ujian dan cara belajar pengolahan permukaan','Membedakan format ujian, contoh pekerjaan, dan perhatian saat mengikuti ujian yang tercantum dalam materi dari penilaian latihan aplikasi.',[
('Tanggal informasi materi dan format ujian','Ringkasan materi berlaku per Juli 2026. Materi menjelaskan bahwa ujian memeriksa keterampilan yang memerlukan pengetahuan atau pengalaman yang cukup, setara dengan Uji Keterampilan Tingkat 3, yaitu tingkat yang memungkinkan seseorang segera melaksanakan pekerjaan pada taraf tertentu tanpa pembinaan atau pelatihan khusus. Formatnya CBT: teori berupa 30 soal benar-salah, praktik berupa 10 soal pilihan ganda tentang penilaian, perencanaan, dan sebagainya. Waktu teori 40 menit dan praktik 40 menit; kanji bahasa Jepang dilengkapi furigana. Istilah praktik pada format ini tidak berarti mengoperasikan mesin sungguhan.'),
('Pisahkan standar kelulusan dan persyaratan peserta','Standar kelulusan dalam materi adalah teori minimal 65% dan praktik minimal 60%. Jika soal orisinal aplikasi dinilai dengan bobot yang sama untuk setiap soal, diperlukan teori minimal 20/30 dan praktik minimal 6/10 secara terpisah; kekurangan salah satunya tidak ditutup dengan nilai gabungan. Ini tidak menjamin bobot resmi yang tidak dipublikasikan. Materi menyebut persyaratan warga asing yang pada prinsipnya sudah genap berusia 17 tahun pada hari ujian, atau genap 18 tahun untuk warga negara Indonesia, serta berniat bekerja di Jepang setelah lulus. Periksa panduan terbaru penyelenggara mengenai pendaftaran, kelayakan, barang bawaan, dan sebagainya; jangan menentukan kelayakan mengikuti ujian kali ini hanya dari keterangan usia dalam materi.'),
('Kategori dan contoh pekerjaan','Contoh yang sesuai dengan kategori pengolahan permukaan logam dalam materi adalah pelapisan listrik, galvanisasi celup panas, anodisasi, dan pemolesan buff. Contoh pekerjaan berbeda dari lingkup pekerjaan yang diizinkan untuk diri sendiri. Pastikan pelatihan, kualifikasi, dan izin kerja untuk setiap peralatan tempat penugasan.'),
('Menjaga keadilan ujian','Materi melarang membawa keluar soal atau jawaban ujian yang sebenarnya, termasuk informasi parsial, serta membagikannya melalui media sosial dan sebagainya, baik secara publik maupun privat. Hal ini dijelaskan sebagai kecurangan serius yang merusak keadilan bagi peserta. Materi menyebut kamera pengawas dan pengawas ujian di lokasi yang memantau perilaku selama ujian. Kecurangan dapat dikenai tindakan tegas, termasuk pembatalan hasil, pencabutan kelayakan ujian di masa depan, dan pelaporan kepada Badan Layanan Imigrasi Jepang. Untuk rincian, ikuti peraturan penyelenggara. Soal aplikasi dibuat sendiri dan bukan reproduksi soal resmi.'),
('Belajar bahasa Jepang dan istilah teknis','Jika bahasa Jepang dalam teks sulit, lanjutkan pula belajar bahasa Jepang dan tanyakan secara spesifik istilah teknis yang tidak dipahami kepada atasan atau rekan kerja. Baca berulang kali dengan memahami maknanya, dan periksa sampai akhir kalimat, termasuk objek, kondisi, dan penyangkalan. Jangan berlatih hanya dengan total 80 menit; kelola dua bagian 40 menit secara terpisah.')],
['Soal untuk menentukan apakah suatu pernyataan benar atau salah.','Contoh pekerjaan yang sesuai dengan kategori.','Bagian akhir kalimat, yang juga penting untuk memahami penyangkalan dan kondisi.'],
'4 menit: tuliskan format, waktu, dan standar teori serta praktik dalam kolom terpisah.\n5 menit: bedakan tanggal informasi materi, keterangan usia, dan pemeriksaan panduan terbaru.\n4 menit: susun empat contoh pekerjaan dan bandingkan kalimat afirmatif serta negatif buatan sendiri.\n2 menit: pastikan cara belajar tanpa membawa keluar soal resmi.',
['Jangan menyamakan kelulusan simulasi dengan kelayakan bekerja atau izin kerja di lapangan. Jangan mengumpulkan, mereproduksi, atau membagikan soal maupun jawaban ujian sebenarnya.'],
'Bedakan tanggal informasi materi dan panduan terbaru. Pastikan dua persyaratan ujian, empat contoh pekerjaan, penanganan informasi yang adil, dan pembacaan sampai akhir kalimat.'))
ID.append(('Memahami keselamatan pekerjaan dasar dan penggunaan alat','Menghubungkan penjelasan kecelakaan kerja dengan tindakan terkait aturan, peralatan yang belum dikenal, alat, dan pelaporan kelainan.',[
('Kecelakaan saat bekerja dan perjalanan kerja','Di lokasi manufaktur terdapat bahaya seperti suhu tinggi, benda berat, mesin, dan bahan kimia. Materi menjelaskan kecelakaan kerja sebagai cedera atau penyakit yang disebabkan pekerjaan atau perjalanan pergi-pulang kerja. Setiap orang berupaya mencegahnya dan mematuhi aturan tempat kerja untuk melindungi diri sendiri maupun orang di sekitarnya. Penetapan hukum kasus tertentu tidak diputuskan hanya dari pembelajaran ini.'),
('Alat yang belum dikenal dan alat yang sudah digunakan','Jangan menyentuh mesin atau alat yang belum dikenal tanpa izin; konfirmasikan kepada atasan. Tangani alat dengan hati-hati, jangan melemparkannya saat menyerahkan atau meletakkannya sembarangan, dan kembalikan ke tempat yang benar setelah digunakan. Merasa tidak ada bahaya yang terlihat bukan alasan mengabaikan hukum atau aturan.'),
('Hentikan dan laporkan kelainan','Jika menemukan suara, bau, atau getaran yang berbeda dari biasanya, hentikan dengan aman mengikuti prosedur peralatan, laporkan fakta dan tindakan kepada atasan, lalu terima instruksi. Jangan menilai bagian dalam aman hanya karena sudah berhenti; pastikan pula kewenangan menyalakan ulang atau memeriksa bagian dalam.')],
['Dalam materi dijelaskan sebagai cedera atau penyakit akibat pekerjaan atau perjalanan pergi-pulang kerja.','Menangani dengan perhatian dan tidak kasar.','Menyampaikan fakta yang berbeda dari biasanya serta tindakan yang telah dilakukan kepada penanggung jawab.'],
'4 menit: susun contoh fiktif saat bekerja dan saat perjalanan kerja.\n5 menit: tulis tindakan ketika menyerahkan dan mengembalikan alat.\n4 menit: buat kalimat konsultasi untuk dua situasi, mesin yang belum dikenal dan suara tidak normal.\n2 menit: tinjau aturan yang melindungi diri sendiri dan orang sekitar.',
['Jangan mencoba menjalankan peralatan yang belum dikenal. Jangan melempar alat. Penghentian, pemeriksaan, dan pengoperasian ulang harus mengikuti prosedur serta kewenangan peralatan.'],
'Pencegahan kecelakaan dilakukan demi diri sendiri dan orang sekitar. Tangani alat dengan hati-hati; jangan melanjutkan sendiri saat belum memahami atau menemukan kelainan.'))
ID.append(('Membedakan sifat asam dan basa dengan acuan pH7','Membedakan sekitar netral dengan sisi asam dan basa dalam contoh pengantar, serta mencatat identitas cairan dan suhu.',[
('Membaca contoh pengantar','Materi menjelaskan pH sebagai indikator derajat keasaman dan kebasaan larutan air. Pada skala pengantar 0–14, pH7 ditunjukkan sebagai netral, sisi di bawah 7 sebagai asam, dan sisi di atasnya sebagai basa. Pada kondisi pengantar yang sama, semakin kecil nilainya semakin kuat sifat asam, dan semakin besar nilainya semakin kuat sifat basa.'),
('Jangan menghilangkan kondisi','Perbandingan dengan netral sekitar 7 adalah contoh pengantar untuk larutan air encer pada suhu ruang. Jangan menghilangkan kondisi suhu atau cairan dan menggeneralisasi bahwa semua cairan selalu berada dalam 0–14. Kaitkan hasil pengukuran dengan identitas cairan, suhu, metode, serta tanggal dan waktu. Jangan memutuskan cairan yang komponennya tidak diketahui sebagai air tidak berbahaya hanya karena angkanya mendekati netral.')],
['Keadaan yang menjadi acuan perbandingan asam dan basa dalam contoh pengantar.','Dalam contoh pengantar, sisi di bawah pH7 yang netral.','Dalam contoh pengantar, sisi di atas pH7 yang netral.'],
'4 menit: dalam contoh pengantar, kelompokkan pH3, 7, dan 10 sebagai asam, netral, dan basa.\n5 menit: baca alasan perbandingan angka berbeda dari penilaian keselamatan cairan.\n4 menit: buat kolom catatan fiktif yang mencakup identitas, suhu, metode, serta tanggal dan waktu.\n2 menit: pastikan 0–14 tidak digeneralisasi untuk semua cairan.',
['Belajar hanya di atas kertas. Jangan mencampur asam dan basa, atau memeriksa cairan tidak dikenal melalui bau, rasa, maupun sentuhan tangan telanjang.'],
'Dalam contoh pengantar, di bawah 7 adalah asam dan di atasnya basa. Pertimbangkan nilai beserta kondisi; pH saja tidak menjamin keselamatan.'))
ID.append(('Membaca contoh berat jenis dengan acuan air 4°C','Memastikan acuan berat jenis dan nilai contoh khusus materi, tanpa mencampurnya dengan satuan massa jenis atau angka tabel lain.',[
('Acuan dan satuan','Materi menggunakan air 4°C sebagai acuan berat jenis zat padat dan cair, dengan berat jenis acuan 1. Berat jenis adalah rasio terhadap massa jenis acuan, sehingga tidak langsung diberi satuan massa jenis seperti g/cm³. Jika volumenya sama, dapat juga dipahami sebagai rasio massa sampel terhadap acuan; bukan membagi langsung dua massa yang volumenya berbeda.'),
('Enam nilai contoh dalam materi','Contoh pada halaman cetak 39 adalah aluminium 2.68, besi 7.87, nikel 8.69, tembaga 8.82, timbal 11.43, dan emas 19.32. Ini merupakan nilai rujukan yang tertulis pada bagian ini; jangan menggantinya tanpa izin dengan nilai pada tabel 21 logam di bagian berikutnya atau sumber lain. Karena terdapat perbedaan akibat paduan dan kondisi, angka ini tidak menjamin nilai tersertifikasi bahan sebenarnya atau nilai tepat yang tidak berubah pada semua suhu. Dalam praktik, ikuti spesifikasi bahan, acuan, suhu, dan metode pemeriksaan yang ditentukan.')],
['Rasio terhadap massa jenis bahan acuan.','Bahan yang menjadi dasar perbandingan.','Nilai contoh yang diperiksa bersama sumber dan kondisinya.'],
'4 menit: tuliskan hubungan air 4°C, berat jenis 1, dan rasio tanpa satuan.\n5 menit: periksa keenam nilai contoh berpasangan dengan nama bahannya.\n4 menit: hitung di atas kertas rasio acuan 20g dan sampel 60g dengan volume sama, lalu buat kolom sumber dan suhu.\n2 menit: tinjau alasan tidak menimpa angka tanpa izin dengan nilai tabel lain.',
['Jangan menggunakan bahan atau cairan yang jenisnya tidak diketahui dengan menganggapnya aman atau sebagai bahan yang ditentukan hanya berdasarkan berat jenis.'],
'Dalam materi, acuan berat jenis adalah air 4°C dengan nilai 1. Pertahankan sumber keenam nilai contoh; jangan menjadikannya pengganti pemeriksaan spesifikasi bahan sebenarnya.'))
write('id','Materi tambahan',ID)
TL=[]
TL.append(('Unawain ang pagkakaiba ng 5S at 4S sa patuloy na gawain','Ihiwalay ang limang elemento ng 5S at ang elementong inaalis sa 4S. Iugnay ang mga pangalan sa araw-araw na kilos.',[
('Panatilihin ang limang elemento','Ang 5S ay pagbubukod, pagsasaayos, paglilinis, pagpapanatili ng kalinisan, at pagdidisiplina sa sarili. Sa pagbubukod, inaalis ang hindi kailangang bagay; sa pagsasaayos, inilalagay ang kailangang bagay sa itinakdang lugar; sa paglilinis, inaalis ang dumi habang napapansin din ang maliliit na abnormalidad gaya ng tagas ng langis. Ang pagpapanatili ng kalinisan ay pagpapanatili ng mabuting kalagayang bunga ng pagbubukod, pagsasaayos, at paglilinis; ang pagdidisiplina sa sarili ay paggawa ng lahat sa napagkasunduang tuntunin bilang nakagawian.'),
('Huwag mapagpalit ang inaalis sa 4S','Nagbibigay ang materyal ng halimbawang tinatawag na 4S ang pagbubukod, pagsasaayos, paglilinis, at pagpapanatili ng kalinisan: ang 5S na inalisan ng pagdidisiplina sa sarili. Ang pagpapalit ng paglilinis ng pananagutan upang tawaging 5S, o ang pagdaragdag ng pananagutan sa 4S, ay hindi ang paliwanag sa pangalang ito. Hindi lamang tandaan ang pangalan; tiyakin din kung aling kilos ang patuloy na gagawin.'),
('Huwag tapusin sa isang beses lamang','Hindi natatapos ang 5S sa isang beses na pag-aayos; ipinagpapatuloy ito araw-araw upang magkaroon ng ligtas at maginhawang lugar ng trabaho at mabubuting produkto. Huwag itapon ang dokumento o ipinagkatiwalang bagay sa sariling pasya. Kapag nakakita ng abnormalidad, ipaalam ito sa namamahala mula sa ligtas na kalagayan. Huwag ipasok ang kamay sa umiikot na bahagi para maglinis.')],
['Tawag sa pinagsamang pagbubukod, pagsasaayos, paglilinis, at pagpapanatili ng kalinisan.','Gawing nakagawian ang mga napagkasunduang tuntunin.','Ipagpatuloy, hindi minsan lamang gawin.'],
'4 minuto: isulat nang magkahiwalay ang mga elemento ng 5S at 4S.\n5 minuto: basahin ang teksto at ipaliwanag ang pagkakaiba ng paglilinis at pagpapanatili ng kalinisan.\n4 minuto: isipin ang isang lugar ng trabaho at magsulat ng tigdalawang araw-araw na kilos at taong namamahala sa pagsusuri.\n2 minuto: balikan kung bakit hindi maaaring ipagpalit ang pananagutan at paglilinis.',
['Sa papel gawin ang pag-aaral. Sundin ang awtoridad at pamamaraang pangkaligtasan ng lugar ng trabaho sa paglilinis, pagtatapon, at paglapit sa kagamitan.'],
'Huwag palitan ng pananagutan ang paglilinis sa 5S. Ang 4S ay tawag na nag-aalis ng pagdidisiplina sa sarili; panatilihin ang mabuting kalagayan araw-araw.'))
TL.append(('Unawain ang gabay sa pagsusulit at paraan ng pag-aaral ng surface treatment','Ihiwalay ang anyo ng pagsusulit, halimbawa ng trabaho, at pag-iingat sa pagkuha nito na nasa materyal mula sa pagmamarka ng pagsasanay sa app.',[
('Petsa ng impormasyon at anyo ng pagsusulit','Ang buod ng materyal ay ayon sa kalagayan noong Hulyo 2026. Ipinaliliwanag nitong sinusuri ang kasanayang nangangailangan ng sapat na kaalaman o karanasan, katumbas ng Antas 3 ng pagsusulit sa kasanayan: antas na agad makagagawa ng trabaho sa isang takdang antas nang walang espesyal na pagpapaunlad o pagsasanay. CBT ang paraan: 30 tanong na tama o mali sa teorya, at 10 tanong na maraming pagpipilian tungkol sa paghatol, pagpaplano, at iba pa sa praktikal. May 40 minuto para sa teorya at 40 minuto para sa praktikal; may furigana ang mga kanji sa wikang Hapon. Ang pangalang praktikal sa paraang ito ay hindi nangangahulugang pagpapatakbo ng aktuwal na makina.'),
('Ihiwalay ang pamantayan at kondisyon ng pagkuha','Ang pamantayan sa pagpasa sa materyal ay hindi bababa sa 65% sa teorya at 60% sa praktikal. Kapag pantay ang puntos ng bawat orihinal na tanong sa app, kailangan nang magkahiwalay ang hindi bababa sa 20/30 sa teorya at 6/10 sa praktikal; hindi mapupunan ang kakulangan ng isa gamit ang pinagsamang puntos. Hindi nito ginagarantiyahan ang hindi inilalathalang opisyal na pagtitimbang ng puntos. Nakasaad sa materyal ang kondisyong dayuhang, bilang tuntunin, ay ganap na 17 taong gulang o higit sa araw ng pagsusulit, o ganap na 18 taong gulang o higit kung mamamayan ng Indonesia, at may balak magtrabaho sa Japan matapos pumasa. Tingnan ang pinakabagong gabay ng tagapagpatupad tungkol sa aplikasyon, pagiging kuwalipikado, mga maaaring dalhin, at iba pa; huwag magpasya kung maaaring kumuha sa pagkakataong ito batay lamang sa edad na nakasulat sa materyal.'),
('Kategorya at halimbawa ng trabaho','Ang mga halimbawang tumutugma sa kategorya ng metal surface treatment sa materyal ay electroplating, hot-dip galvanizing, anodizing, at buff polishing. Magkaiba ang halimbawa ng trabaho at saklaw ng trabahong pinahihintulutan sa iyo. Tiyakin ang pagsasanay, kuwalipikasyon, at pahintulot sa trabaho para sa bawat kagamitang itinalaga sa iyo.'),
('Panatilihin ang pagiging patas ng pagsusulit','Ipinagbabawal ng materyal ang paglabas ng aktuwal na tanong o sagot, kabilang ang bahagyang impormasyon, at pagbabahagi sa social media at iba pa, pampubliko man o pribado. Ipinaliliwanag itong malubhang pandarayang sumisira sa pagiging patas para sa mga kumukuha. Nakasaad na may mga surveillance camera at tagapangasiwa sa lugar na nagmamasid sa kilos habang kumukuha. Maaaring magkaroon ng mahihigpit na hakbang laban sa pandaraya: pagpapawalang-bisa ng resulta, pag-aalis ng karapatang kumuha sa hinaharap, at pag-uulat sa Immigration Services Agency of Japan, bukod sa iba pa. Sundin ang mga tuntunin ng tagapagpatupad para sa detalye. Sariling gawa ang mga tanong ng app at hindi muling pagbuo ng opisyal na tanong.'),
('Pag-aralan ang wikang Hapon at teknikal na salita','Kung mahirap ang wikang Hapon ng teksto, magpatuloy din sa pag-aaral ng Hapon at magtanong nang tiyak sa superbisor o katrabaho tungkol sa hindi nauunawaang teknikal na salita. Unawain ang kahulugan sa paulit-ulit na pagbasa at suriin hanggang dulo ng pangungusap, kasama ang bagay na tinutukoy, kondisyon, at pagtanggi. Huwag magsanay batay lamang sa kabuuang 80 minuto; pamahalaan nang magkahiwalay ang dalawang bahaging tig-40 minuto.')],
['Tanong kung tama o mali ang isang pahayag.','Halimbawa ng trabahong tumutugma sa kategorya.','Huling bahagi ng pangungusap, mahalaga rin sa pag-unawa sa pagtanggi at kondisyon.'],
'4 minuto: isulat sa magkahiwalay na hanay ang anyo, oras, at pamantayan ng teorya at praktikal.\n5 minuto: ihiwalay ang petsa ng materyal, nakasulat na edad, at pagsuri sa pinakabagong gabay.\n4 minuto: ayusin ang apat na halimbawa ng trabaho at paghambingin ang sariling gawang pangungusap na paturol at pasalungat.\n2 minuto: tiyakin ang paraan ng pag-aaral na hindi inilalabas ang opisyal na tanong.',
['Huwag ipagkamali ang pagpasa sa mock exam bilang kuwalipikasyon sa pagtatrabaho o pahintulot sa aktuwal na gawain. Huwag mangolekta, bumuo muli, o magbahagi ng aktuwal na tanong o sagot sa pagsusulit.'],
'Ihiwalay ang petsa ng materyal at pinakabagong gabay. Tiyakin ang dalawang kondisyon ng pagsusulit, apat na halimbawa ng trabaho, patas na paghawak ng impormasyon, at pagbasa hanggang dulo ng pangungusap.'))
TL.append(('Unawain ang kaligtasan sa batayang gawain at paghawak ng kasangkapan','Iugnay ang paliwanag ng aksidenteng may kaugnayan sa trabaho sa kilos tungkol sa tuntunin, hindi kilalang kagamitan, kasangkapan, at pag-uulat ng abnormalidad.',[
('Aksidente sa trabaho at pagpasok o pag-uwi','May mga panganib sa lugar ng pagmamanupaktura gaya ng mataas na temperatura, mabibigat na bagay, makina, at kemikal. Ipinapaliwanag ng materyal ang aksidenteng may kaugnayan sa trabaho bilang pinsala o pagkakasakit na dulot ng trabaho o pagpasok at pag-uwi. Bawat isa ay nagsisikap na umiwas dito at sumusunod sa tuntunin ng lugar ng trabaho para protektahan ang sarili at ang mga nasa paligid. Hindi pinapasya ang legal na pagkilala sa isang partikular na kaso batay lamang sa pag-aaral na ito.'),
('Hindi kilalang kasangkapan at nagamit na kasangkapan','Huwag basta hawakan ang hindi kilalang makina o kasangkapan; magtanong sa superbisor. Ingatan ang kasangkapan, huwag ihagis kapag ipinapasa o ilapag nang magulo, at ibalik sa tamang lugar pagkatapos gamitin. Ang pakiramdam na walang nakikitang panganib ay hindi dahilan para balewalain ang batas o tuntunin.'),
('Ihinto at ipaalam ang abnormalidad','Kapag napansin ang kakaibang tunog, amoy, o pagyanig, ligtas na ihinto ayon sa itinakdang paraan ng kagamitan, iulat sa superbisor ang mga katotohanan at ginawa, at humingi ng tagubilin. Huwag ipalagay na ligtas ang loob dahil huminto lamang ito; tiyakin din ang awtoridad para sa muling pagpapatakbo at panloob na inspeksiyon.')],
['Sa materyal, inilalarawan bilang pinsala o sakit na dulot ng trabaho o pagpasok at pag-uwi.','Paghawak nang maingat at hindi magaspang.','Pagpapaalam sa namamahala ng naiibang katotohanan at ginawang pagtugon.'],
'4 minuto: ayusin ang kathang-isip na kaso habang nagtatrabaho at habang pumapasok o umuuwi.\n5 minuto: isulat ang kilos sa pagpasa at pagbabalik ng kasangkapan.\n4 minuto: gumawa ng mensahe ng pagkonsulta sa dalawang sitwasyon: hindi kilalang makina at kakaibang tunog.\n2 minuto: balikan ang tuntuning nagpoprotekta sa sarili at sa paligid.',
['Huwag subukang patakbuhin ang hindi kilalang kagamitan. Huwag maghagis ng kasangkapan. Sundin ang pamamaraan at awtoridad ng kagamitan sa paghinto, inspeksiyon, at muling pagpapatakbo.'],
'Ang pag-iwas sa aksidente ay para sa sarili at sa paligid. Ingatan ang kasangkapan; huwag magpatuloy sa sariling pasya sa hindi alam o abnormal na sitwasyon.'))
TL.append(('Ihiwalay ang asido at alkalino gamit ang pH7 na batayan','Ihiwalay ang malapit sa neutral at ang panig na asido o alkalino sa panimulang halimbawa, at itala ang pagkakakilanlan ng likido at temperatura.',[
('Pagbasa ng panimulang halimbawa','Ipinapaliwanag ng materyal ang pH bilang sukatan ng antas ng pagkaasido at pagkaalkalino ng solusyong tubig. Sa panimulang iskalang 0–14, ang pH7 ay neutral, ang mas mababa sa 7 ay asido, at ang mas mataas ay alkalino. Sa parehong panimulang kondisyon, mas mababang bilang ay mas malakas na pagkaasido at mas mataas na bilang ay mas malakas na pagkaalkalino.'),
('Huwag alisin ang kondisyon','Ang paghahambing sa neutral na humigit-kumulang 7 ay panimulang halimbawa ng malabnaw na solusyong tubig sa temperatura ng silid. Huwag alisin ang kondisyon ng temperatura o likido at sabihing lahat ng likido ay laging nasa 0–14. Iugnay sa sinusukat na halaga ang pagkakakilanlan ng likido, temperatura, paraan, at petsa at oras. Huwag ituring na hindi mapanganib na tubig ang likidong hindi alam ang sangkap dahil lamang malapit sa neutral ang bilang.')],
['Kalagayang batayan sa paghahambing ng asido at alkalino sa panimulang halimbawa.','Sa panimulang halimbawa, ang panig na mas mababa sa neutral na pH7.','Sa panimulang halimbawa, ang panig na mas mataas sa neutral na pH7.'],
'4 minuto: sa panimulang halimbawa, uriin ang pH3, 7, at 10 bilang asido, neutral, at alkalino.\n5 minuto: basahin kung bakit magkaiba ang paghahambing ng bilang at paghatol sa kaligtasan ng likido.\n4 minuto: gumawa ng kathang-isip na talaang may pagkakakilanlan, temperatura, paraan, at petsa at oras.\n2 minuto: tiyaking hindi ilalahat ang 0–14 sa lahat ng likido.',
['Sa papel lamang mag-aral. Huwag paghaluin ang asido at alkalino, o suriin ang hindi kilalang likido sa pag-amoy, pagtikim, o paghawak nang walang guwantes.'],
'Sa panimulang halimbawa, asido ang mas mababa sa 7 at alkalino ang mas mataas. Isaalang-alang ang halaga at kondisyon; hindi ginagarantiyahan ng pH lamang ang kaligtasan.'))
TL.append(('Basahin ang halimbawa ng specific gravity batay sa tubig sa 4°C','Tiyakin ang batayan ng specific gravity at ang mga halimbawang halaga sa mismong materyal; huwag ipaghalo sa yunit ng densidad o bilang mula sa ibang talahanayan.',[
('Batayan at yunit','Ginagamit ng materyal ang tubig sa 4°C bilang batayan ng specific gravity ng solid at likido, at ipinapakitang 1 ang specific gravity ng batayan. Ang specific gravity ay ratio sa densidad ng batayan, kaya hindi basta nilalagyan ng yunit ng densidad gaya ng g/cm³. Kung pareho ang volume, maaari rin itong unawain bilang ratio ng mass ng sample at batayan; hindi ito basta paghahati ng dalawang mass na magkaiba ang volume.'),
('Anim na halimbawang halaga sa materyal','Ang mga halimbawa sa nakalimbag na pahina 39 ay aluminum 2.68, bakal 7.87, nickel 8.69, copper 8.82, lead 11.43, at ginto 19.32. Mga halagang sanggunian ito na nakasulat sa bahaging ito; huwag basta palitan ng halaga sa talahanayan ng 21 metal sa bandang huli o sa ibang materyal. May pagkakaiba dahil sa alloy at kondisyon, kaya hindi nito ginagarantiyahan ang sertipikadong halaga ng aktuwal na materyal o eksaktong halagang hindi nagbabago sa lahat ng temperatura. Sa gawain, sundin ang itinakdang espesipikasyon ng materyal, batayan, temperatura, at paraan ng pagsusuri.')],
['Ratio sa densidad ng sangguniang materyal.','Materyal na nagsisilbing batayan ng paghahambing.','Halimbawang halagang sinusuri kasama ang pinagmulan at kondisyon.'],
'4 minuto: isulat ang ugnayan ng tubig sa 4°C, specific gravity 1, at ratio na walang yunit.\n5 minuto: tiyakin ang anim na halimbawang halaga na kapareha ang pangalan ng materyal.\n4 minuto: sa papel, kunin ang ratio ng batayang 20g at sample na 60g na pareho ang volume, at gumawa ng hanay para sa pinagmulan at temperatura.\n2 minuto: balikan kung bakit hindi dapat basta patungan ng halaga mula sa ibang talahanayan.',
['Huwag gamitin ang materyal o likidong hindi alam ang uri sa pag-aakalang ligtas o iyon ang itinakdang materyal batay lamang sa specific gravity.'],
'Sa materyal, tubig sa 4°C na may halagang 1 ang batayan ng specific gravity. Panatilihin ang pinagmulan ng anim na halimbawang halaga; huwag itong ipalit sa pagsusuri ng espesipikasyon ng aktuwal na materyal.'))
write('tl','Karagdagang materyal',TL)
